import{_ as t,o as r,c as o,ai as s}from"./chunks/framework.C33Uq6m-.js";const m=JSON.parse('{"title":"Exporter vos donnees","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/export.md","filePath":"fr/guide/export.md"}'),a={name:"fr/guide/export.md"};function i(n,e,d,l,u,p){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="exporter-vos-donnees" tabindex="-1">Exporter vos donnees <a class="header-anchor" href="#exporter-vos-donnees" aria-label="Permalink to &quot;Exporter vos donnees&quot;">​</a></h1><p>LLMxRay genere des donnees riches -- benchmarks, sessions, conversations, definitions d&#39;outils et rapports systeme. Chaque donnee que vous creez est exportable. Vos donnees restent locales jusqu&#39;a ce que vous choisissiez de les partager.</p><h2 id="ce-qui-peut-etre-exporte" tabindex="-1">Ce qui peut etre exporte <a class="header-anchor" href="#ce-qui-peut-etre-exporte" aria-label="Permalink to &quot;Ce qui peut etre exporte&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Formats</th><th>Contenu</th></tr></thead><tbody><tr><td>Comparer</td><td>JSON, Markdown, Partage</td><td>Prompts, sorties, metriques, Token Tax</td></tr><tr><td>Benchmark</td><td>JSON, CSV, Markdown</td><td>Questions, reponses, precision, resultats par categorie</td></tr><tr><td>Session</td><td>JSON, Markdown, Token CSV</td><td>Prompt, reponse, metriques, latences par token</td></tr><tr><td>Chat</td><td>JSON, Markdown, Texte</td><td>Conversation complete avec horodatages</td></tr><tr><td>Atelier d&#39;Outils</td><td>JSON</td><td>Definitions d&#39;outils avec implementations</td></tr><tr><td>Systeme</td><td>JSON, Markdown</td><td>Materiel, statut Ollama, modeles, stockage</td></tr></tbody></table><h2 id="formats-d-export" tabindex="-1">Formats d&#39;export <a class="header-anchor" href="#formats-d-export" aria-label="Permalink to &quot;Formats d&#39;export&quot;">​</a></h2><ul><li><strong>JSON</strong> -- Donnees structurees completes. Pour scripts, analyses, reimportation.</li><li><strong>CSV</strong> -- Donnees tabulaires plates. Ouvrir dans Excel, Google Sheets ou pandas.</li><li><strong>Markdown</strong> -- Rapports formates. A coller dans des documents, blogs ou GitHub.</li><li><strong>JSONL</strong> -- JSON delimite par lignes pour l&#39;export de donnees d&#39;entrainement.</li><li><strong>Texte</strong> -- Transcriptions de conversations en texte brut.</li></ul><h2 id="comment-exporter" tabindex="-1">Comment exporter <a class="header-anchor" href="#comment-exporter" aria-label="Permalink to &quot;Comment exporter&quot;">​</a></h2><ol><li>Cherchez le bouton <strong>Exporter</strong> (icone de telechargement) sur toute page de resultats.</li><li>Cliquez pour voir les formats disponibles.</li><li>Selectionnez un format -- le fichier se telecharge immediatement.</li><li>Pour partager : choisissez <strong>&quot;Partager sur GitHub Discussions&quot;</strong> pour publier vos resultats.</li></ol><h2 id="partage-sur-github-discussions" tabindex="-1">Partage sur GitHub Discussions <a class="header-anchor" href="#partage-sur-github-discussions" aria-label="Permalink to &quot;Partage sur GitHub Discussions&quot;">​</a></h2><p>Disponible sur les pages Comparer et Benchmark. La fonction de partage pre-remplit un post GitHub Discussion avec votre rapport formate. Vous ajoutez vos propres commentaires et relisez le tout avant de publier. Rien n&#39;est envoye sans votre action explicite.</p><ol><li>Cliquez sur <strong>&quot;Partager sur GitHub Discussions&quot;</strong> dans le menu Exporter.</li><li>Un dialogue s&#39;ouvre avec un apercu du rapport markdown.</li><li>Ajoutez vos commentaires -- decrivez ce que vous avez decouvert.</li><li>Cliquez sur <strong>&quot;Ouvrir GitHub Discussions&quot;</strong> pour etre redirige vers GitHub avec le rapport pre-rempli.</li><li>Vous relisez et soumettez le post vous-meme -- rien n&#39;est publie sans votre consentement.</li></ol><h2 id="confidentialite-des-donnees" tabindex="-1">Confidentialite des donnees <a class="header-anchor" href="#confidentialite-des-donnees" aria-label="Permalink to &quot;Confidentialite des donnees&quot;">​</a></h2><blockquote><p>Vos donnees ne quittent jamais votre machine sauf si vous choisissez de les partager. Tous les exports se telechargent sur votre systeme de fichiers local. La fonction Partager ouvre une URL GitHub -- vous controlez ce qui est publie.</p></blockquote>',13)])])}const h=t(a,[["render",i]]);export{m as __pageData,h as default};
